// Colores del dashboard (validados en tema claro y oscuro)
const COLOR_VENTAS = '#008300';
const COLOR_VENTAS_SUAVE = 'rgba(0, 131, 0, 0.55)';
const COLOR_GASTOS = '#c98500';
const COLOR_CONTEXTO = '#8e8e8e';

const tema = context.grafana.theme;
const colorTexto = tema.colors.text.secondary;
const colorBorde = tema.colors.border.weak;
const marco = context.panel.data.series[0];
// valores de una columna; Grafana los entrega como arreglo (o como vector
// en versiones viejas, por eso el .buffer)
const columna = (nombre) => {
    const campo = marco && marco.fields.find((f) => f.name === nombre);
    return campo ? Array.from(campo.values.buffer || campo.values) : [];
};
const moneda = new Intl.NumberFormat('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const entero = new Intl.NumberFormat('es-GT', { maximumFractionDigits: 0 });
const sinDatos = () => ({
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        title: {
            text: 'Sin datos en el rango seleccionado',
            left: 'center',
            top: 'middle',
            textStyle: { color: colorTexto, fontSize: 14, fontWeight: 'normal' },
        },
    },
});

// Paleta clasica de Grafana (la misma que usa por defecto en sus graficas)
const PALETA = ['green', 'yellow', 'blue', 'orange', 'red', 'purple', 'light-blue', 'dark-yellow', 'semi-dark-green', 'dark-purple']
    .map((nombre) => tema.visualization.getColorByName(nombre));

const semanas = columna('Semana');
const dias = columna('Día');
const ventas = columna('Venta');
if (!semanas.length) return sinDatos();

const DIAS = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'];
const orden = [];
const porSemana = {};
semanas.forEach((s, i) => {
    if (!porSemana[s]) {
        porSemana[s] = new Array(7).fill(null); // null = dia que no ha llegado
        orden.push(s);
    }
    porSemana[s][Number(dias[i]) - 1] = Number(ventas[i]);
});
const reciente = orden[orden.length - 1]; // los datos vienen de la mas vieja a la mas nueva

const series = orden.map((s, i) => {
    const esReciente = s === reciente;
    // la semana mas reciente toma el primer color, las anteriores siguen la paleta
    const color = PALETA[(orden.length - 1 - i) % PALETA.length];
    return {
        name: s,
        type: 'line',
        data: porSemana[s],
        connectNulls: false, // la linea se corta donde termina la semana en curso
        symbol: 'circle',
        symbolSize: esReciente ? 8 : 5,
        z: esReciente ? 3 : 2,
        lineStyle: { width: esReciente ? 3 : 1.5, color },
        itemStyle: { color },
        emphasis: { focus: 'series', lineStyle: { width: 3 } },
        blur: { lineStyle: { opacity: 0.15 }, itemStyle: { opacity: 0.15 } },
    };
});

return {
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'axis',
            order: 'seriesDesc', // todas las semanas de ese dia, de la mas reciente a la mas antigua
            valueFormatter: (v) => (v == null ? '—' : 'Q ' + moneda.format(v)),
        },
        legend: { type: 'scroll', bottom: 0, icon: 'roundRect', textStyle: { color: colorTexto } },
        grid: { left: 8, right: 16, top: 16, bottom: 40, containLabel: true },
        xAxis: {
            type: 'category',
            data: DIAS,
            boundaryGap: false,
            axisLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto },
        },
        yAxis: {
            type: 'value',
            min: 0,
            splitLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto, formatter: (v) => entero.format(v) },
        },
        series,
    },
};

