// Ventas por semana y tienda: barras agrupadas, una serie por tienda.
// Usa los datos de "Ventas por semana" (panel 8) mediante el origen "-- Dashboard --".
const tema = context.grafana.theme;
// Paleta clasica de Grafana (la misma que usa por defecto en sus graficas)
const PALETA = ['green', 'yellow', 'blue', 'orange', 'red', 'purple', 'light-blue', 'dark-yellow', 'semi-dark-green', 'dark-purple']
    .map((nombre) => tema.visualization.getColorByName(nombre));
const colorTexto = tema.colors.text.secondary;
const colorBorde = tema.colors.border.weak;
const marco = context.panel.data.series[0];
// valores de una columna; Grafana los entrega como arreglo (o como vector
// en versiones viejas, por eso el .buffer)
const columna = (nombre) => {
    const campo = marco && marco.fields.find((f) => f.name === nombre);
    return campo ? Array.from(campo.values.buffer || campo.values) : [];
};
const moneda = new Intl.NumberFormat('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const entero = new Intl.NumberFormat('es-GT', { maximumFractionDigits: 0 });
const sinDatos = () => ({
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        title: {
            text: 'Sin datos en el rango seleccionado',
            left: 'center',
            top: 'middle',
            textStyle: { color: colorTexto, fontSize: 14, fontWeight: 'normal' },
        },
    },
});

const filaSemana = columna('Semana');
const filaTienda = columna('Tienda');
const filaVenta = columna('Venta').map(Number);
const filaEnCurso = columna('En curso').map(Number);
if (!filaSemana.length) return sinDatos();

// semanas y tiendas en el orden en que llegan (semana de la mas vieja a la mas nueva)
const semanas = [];
const enCurso = [];
const tiendas = [];
filaSemana.forEach((s, i) => {
    if (!semanas.includes(s)) {
        semanas.push(s);
        enCurso.push(filaEnCurso[i]);
    }
    if (!tiendas.includes(filaTienda[i])) tiendas.push(filaTienda[i]);
});
const valores = {};
tiendas.forEach((t) => { valores[t] = new Array(semanas.length).fill(0); });
filaSemana.forEach((s, i) => { valores[filaTienda[i]][semanas.indexOf(s)] = filaVenta[i]; });

const pocas = semanas.length * tiendas.length <= 24; // con muchas barras los valores se enciman
const series = tiendas.map((t, k) => {
    const color = PALETA[k % PALETA.length];
    return {
        name: t,
        type: 'bar',
        barMaxWidth: 36,
        data: valores[t].map((v, i) => ({
            value: v,
            itemStyle: { color, borderRadius: [3, 3, 0, 0], opacity: enCurso[i] ? 0.45 : 1 },
        })),
        label: { show: pocas, position: 'top', color: colorTexto, formatter: (p) => entero.format(p.value) },
        emphasis: { focus: 'series' },
    };
});

return {
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'axis',
            axisPointer: { type: 'shadow' },
            order: 'valueDesc',
            formatter: (p) => {
                const i = p[0].dataIndex;
                const total = tiendas.reduce((a, t) => a + valores[t][i], 0);
                const filas = p
                    .slice()
                    .sort((a, b) => b.value - a.value)
                    .map((x) => x.marker + x.seriesName + ': <b>Q ' + moneda.format(x.value) + '</b>')
                    .join('<br/>');
                return 'Semana del ' + semanas[i] + (enCurso[i] ? ' (en curso)' : '') + '<br/>' + filas +
                    '<br/>Total: <b>Q ' + moneda.format(total) + '</b>';
            },
        },
        legend: { type: 'scroll', bottom: 0, icon: 'roundRect', textStyle: { color: colorTexto } },
        grid: { left: 8, right: 16, top: 28, bottom: 40, containLabel: true },
        xAxis: {
            type: 'category',
            data: semanas,
            axisLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto },
        },
        yAxis: {
            type: 'value',
            min: 0,
            splitLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto, formatter: (v) => entero.format(v) },
        },
        series,
    },
};

